INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 46, 'theory', 'Quiz: async iterators and context managers');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 46, 0, 'Which exception signals the end of an async iterator?', '["StopIteration", "StopAsyncIteration", "EOFError", "CancelledError"]', 1, 'The __anext__ coroutine raises StopAsyncIteration when there are no more items.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 46, 1, 'What can''t you do inside an async generator?', '["Use await", "Use yield", "Return a value with return", "Use try/finally"]', 2, 'return with a value is a SyntaxError; a bare return is allowed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 46, 2, 'What happens to the finally block inside a generator if you leave async for with break?', '["It runs at once", "An error is raised", "It never runs", "It does not run at once: the generator stays suspended until it is closed"]', 3, 'Close the generator with aclose() or an async with aclosing(...) block.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 46, 3, 'What does the @asynccontextmanager decorator do?', '["Makes a function synchronous", "Runs the function in a thread", "Turns an async generator into an async context manager", "Caches the result"]', 2, 'Before yield is opening, after yield is closing, and try/finally guarantees cleanup on error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 46, 4, 'Can you suppress asyncio.CancelledError with a broad except?', '["No: cancellation must propagate outward, otherwise the task can''t be stopped", "Yes, you should: it makes the program more robust", "Yes, if we log it", "Only in tests"]', 0, 'Catch specific errors, and after handling, raise the cancellation further.');
